    """Clockwise rotation (0/90/180/270) needed to show the frame upright, like ffmpeg's autorotate."""
    deg = None
    try:
        deg = first_frame.rotation  # PyAV >= 13: counter-clockwise angle from the display matrix
    except Exception:
        pass
