        try:  # old-style "rotate" tag (clockwise degrees)
            tag = stream.metadata.get("rotate")
            if tag is not None:
                return int(round(float(tag))) % 360
        except Exception:
            pass
        return 0
    return int(round(-float(deg))) % 360


